import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 15 · Christmas tips only, new direction (Vinicius, 2/11/2026): do this, avoid that, decorating
# 9 Christmas Decorating Mistakes Grandma Would Never Make (Do This Instead)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, come sit with me a minute. I drove past the new houses by the highway last night, and I counted. Eleven inflatable snowmen. Four of them were lying face down in the yard. And I thought, my mother would have laughed until she cried. Because in eighty years of Christmases, I've learned that a beautiful house at Christmas has nothing to do with how much you buy.""",
   "Christmas lights house night snow", "FACE DOWN IN THE YARD")
sc("""So tonight I'm going to tell you the nine decorating mistakes I see every single year. The ones my mother and Grandma Pearl would never have made. And for every one, I'll tell you exactly what to do instead. Most of it costs nothing. Some of it will save you money. And all of it will make your house feel like Christmas the moment somebody walks in the door.""",
   "vintage Christmas living room decorated tree", "NINE MISTAKES")

ch("1. Too many colors")
sc("""Mistake number one. Too many colors. Pink and purple and teal and silver and gold and red, all on the same tree. It looks like a candy store exploded, honey. Your eye doesn't know where to rest, so it doesn't rest anywhere, and the tree just looks busy instead of beautiful.""",
   "colorful Christmas tree ornaments", "A CANDY STORE EXPLODED")
sc("""Do this instead. Pick two colors and one metal. Red and green with gold. Blue and white with silver. Cream and red with brass. That's it. My mother did red and gold every year of my childhood, with the glass balls from Woolworth's, and people stopped on the sidewalk to look in our window. When everything matches, even cheap ornaments look expensive.""",
   "red gold Christmas tree ornaments", "TWO COLORS, ONE METAL")

sc("""And one more thing about color, sweetheart. Pick your colors before you go to the store, and write them on a piece of paper in your purse. Because the store is designed to make you fall in love with everything. My mother used to say, if it isn't red or gold, it stays on the shelf, Dorothy. She said it out loud, to herself, right there in the aisle.""",
   "Christmas ornaments store shelf", "WRITE IT DOWN")

ch("2. Lights on the outside only")
sc("""Mistake number two. Wrapping the lights around the outside of the tree like a bandage. Round and round, only on the tips. From across the room the tree looks dark in the middle, like a hole, and all the light sits on the surface.""",
   "Christmas tree lights decorating", "LIKE A BANDAGE")
sc("""Do this instead. Start at the trunk, at the bottom. Take each string in toward the trunk and back out to the tip of the branch, in and out, branch by branch, all the way up. It takes longer, I know. But the tree glows from the inside, like a lantern. My father did it every year with a cigarette in his mouth and Danny holding the plug. And here's the rule, sweetheart: about a hundred lights for every foot of tree.""",
   "Christmas tree glowing lights night room", "A HUNDRED PER FOOT")

sc("""And avoid this too, honey. Never mix the warm white lights and the cold blue white lights on the same tree. The warm ones look like candlelight, the cold ones look like a hospital hallway, and together they fight. Check the box before you buy. And test every string on the floor before it goes on the tree, not after. Ask me how I know.""",
   "warm white Christmas lights", "TEST THEM ON THE FLOOR")

ch("3. Ornaments on top of each other")
sc("""Mistake number three. Ornaments all hung on the very tips of the branches, and all at the front, where you can see them from the couch. Then the back of the tree is bare, and the ornaments in front are crowded together, clinking every time somebody walks by.""",
   "Christmas ornaments hanging tree branch", "ALL ON THE TIPS")
sc("""Do this instead. Big plain balls go first, deep inside, near the trunk. They fill the holes and bounce the light around. Then the medium ones in the middle of the branch. And your special ornaments, the ones with a story, go last, right out on the tips where people can see them. Grandma Pearl always said a tree should have depth, like a good pie. Layers, honey. Layers.""",
   "Christmas tree ornaments close up", "LAYERS, HONEY")

ch("4. Buying everything new")
sc("""Mistake number four. Throwing out last year's decorations and buying a whole new theme every December. I see people at the store with three carts. And in January the old ones go to the curb. That's not Christmas, sweetheart. That's shopping.""",
   "Christmas decorations store shopping", "THREE CARTS")
sc("""Do this instead. Buy one good thing a year, and keep it forever. My mother bought one glass ornament every Christmas from the time she was married in nineteen forty-one. By the time I had my own house, there were twenty-five of them, and every one had a year on it and a story. That's what makes a tree yours. Not a theme from a catalog. A history.""",
   "antique glass Christmas ornaments", "ONE GOOD THING A YEAR")
sc("""And use what's free. Pine cones from the park. Orange slices dried in a low oven. Cinnamon sticks tied with string. Holly from the neighbor's bush, if you ask first. In nineteen fifty-three, our whole mantel was pine branches and pine cones Danny and I picked up behind the church, and it was the prettiest mantel on Elm Street.""",
   "pine cones Christmas mantel decoration", "FREE FROM THE PARK")

sc("""And here's how to keep them, so they last. When you take the tree down, wrap each glass ornament in a sheet of newspaper or tissue, and put them in egg cartons. A dozen to a carton. My mother's egg cartons from the nineteen sixties are still in my hall closet, with her handwriting on the lid. Kitchen balls. Danny's star. Pearl's bells. Never pack them in a plastic bag all together, or you'll find glitter and broken glass next year.""",
   "egg carton ornaments storage", "EGG CARTONS")

ch("5. Forgetting the smell")
sc("""Mistake number five. A house that looks like Christmas but smells like nothing. Or worse, smells like one of those plug-in things that gives you a headache. You can have the most beautiful tree in the county, but if the house doesn't smell like Christmas, it doesn't feel like Christmas.""",
   "Christmas candles home interior", "IT SMELLS LIKE NOTHING")
sc("""Do this instead. Make a simmer pot, honey. A pot of water on the back of the stove with orange peels, a few cinnamon sticks, a handful of whole cloves, and a little splash of vanilla. Keep it on low all afternoon, and add water when it gets low. My mother kept one going every Saturday in December. When my father came home from the plant, he'd open the door and just stand there breathing.""",
   "orange cinnamon cloves pot stove", "THE SIMMER POT")

sc("""One more smell, honey, and it's free. Bring in a few fresh pine or cedar branches and lay them on the mantel or across the top of a picture frame. When the heat comes on, the whole room smells like the woods. Ask at the tree lot for the branches they cut off the bottoms. They'll give them to you for nothing, because otherwise they throw them away.""",
   "fresh pine branches mantel Christmas", "ASK AT THE TREE LOT")

ch("6. Too much in the yard")
sc("""Mistake number six. The yard that looks like a parking lot for Santa. Blow-up snowmen, a plastic reindeer, a light-up candy cane, a train, a flashing sign, all crowded on one little lawn, every one a different color, blinking at a different speed.""",
   "Christmas yard decorations inflatable", "A PARKING LOT FOR SANTA")
sc("""Do this instead. Pick one thing and do it well. A wreath on the door with a big red bow. White candles in every window, one in each, so the house glows from the street. Maybe a string of white lights along the porch rail. That's it. On Elm Street in the fifties, every house had a candle in the window, and walking home from church on Christmas Eve, the whole street looked like a painting.""",
   "Christmas wreath front door red bow", "ONE THING, DONE WELL")

ch("7. Decorating too early")
sc("""Mistake number seven. Putting it all up the day after Halloween. By the middle of December the tree is dry, the needles are falling, you're tired of looking at it, and Christmas hasn't even started yet. And a dry tree is dangerous too, sweetheart. Never forget that.""",
   "Christmas tree dry needles floor", "TIRED BY DECEMBER")
sc("""Do this instead. Decorate in steps, the way we did. The wreath and the window candles after Thanksgiving. The mantel the first week of December. The tree two weeks before Christmas. And the manger last, on Christmas Eve, with the baby Jesus put in at midnight. Every week the house gets a little more Christmas, and the waiting is half the joy. My mother used to say December is the present. Christmas is just the bow.""",
   "family decorating Christmas tree together", "DECEMBER IS THE PRESENT")

sc("""And whatever you do, sweetheart, water the tree every morning, keep it three feet from the heater and the fireplace, and turn the lights off when you go to bed or leave the house. In nineteen fifty-six, a family on the other side of Mansfield lost their house on the twenty-ninth of December from a dry tree. My father made us check the water every morning after that, and so do I.""",
   "watering Christmas tree stand", "WATER IT EVERY MORNING")

ch("8. Hiding the real stuff")
sc("""Mistake number eight. A house that looks like a magazine page, but nothing in it belongs to the family. All store-bought, all perfect, all the same as the house next door. And the children's paper angels, the clay ornament from second grade, go in a box in the basement because they don't match.""",
   "handmade Christmas ornaments children", "NOTHING BELONGS TO YOU")
sc("""Do this instead. Give the handmade things the best spot. Right in front, at eye level. I still hang the cardboard star Danny made in nineteen fifty-one, with too much glitter and his name spelled wrong. Every year somebody asks about it, and every year I get to tell them about my brother. That's what decorations are for, honey. They're for telling stories.""",
   "homemade star ornament Christmas tree", "THEY'RE FOR STORIES")

sc("""Here's a tip for the little ones. Give every child one ornament of their own each year, with their name and the year on the back. When they grow up and have their first tree, you put all of them in a box and give it to them. My daughter cried when I gave her hers. Twenty-two ornaments, from the paper one when she was three to the glass one the year she got married. Her whole childhood, in a shoebox.""",
   "child hanging ornament Christmas tree", "THEIR WHOLE CHILDHOOD")

ch("9. Forgetting the table")
sc("""Mistake number nine. Spending all the money on the tree and the yard, and then putting Christmas dinner on a bare table with paper plates. The table is where the family actually sits together, sweetheart. It deserves more than the yard does.""",
   "Christmas dinner table setting", "PAPER PLATES")
sc("""Do this instead. A white tablecloth, ironed. A long runner of pine branches down the middle, with a few red apples and three white candles, all different heights. And at every plate, a little name card that the children write. That's all. My mother did that table every year, and when I close my eyes I can still see the candlelight on Grandma Pearl's face.""",
   "Christmas table candles pine centerpiece", "CANDLES OF DIFFERENT HEIGHTS")

sc("""And avoid this at the table, honey. Don't make the centerpiece so tall that people can't see each other. Keep it lower than your chin when you're sitting down. And never use scented candles at dinner. They fight with the turkey and the pie. Plain white candles at the table, and save the smell for the stove.""",
   "Christmas table centerpiece low candles", "LOWER THAN YOUR CHIN")

ch("Grandma's rule")
sc("""So here's the whole lesson, if you only remember one thing. Less, but better. Two colors. Lights from the inside. One good ornament a year. A pot on the stove. One beautiful thing in the yard. Decorate a little at a time. Put the children's things in front. And give the table your best.""",
   "cozy Christmas living room fireplace", "LESS, BUT BETTER")
sc("""And tell me in the comments, sweetheart. What's the one ornament on your tree that has a story? I read every one of them, and tomorrow I'll tell you how my mother wrapped presents with no money at all, so pretty that nobody wanted to open them. Good night, honey. Merry Christmas.""",
   "Christmas tree ornament close up warm light", "WHAT'S YOUR ORNAMENT?")

for s in S:  # documentary look: four photos per scene and the six rotating camera moves
    s["cuts"], s["moves"] = 4, True

